/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    TOWER_ANDROID_PACKAGE, TOWER_PLAYER_INFO_FILENAME, TOWER_TOOL_EXPORT_FILENAME, TOWER_SAVE_FILENAMES, TOWER_ANDROID_TOOL_EXPORT_RELATIVE, towerAndroidExportPaths, TOWER_MACOS_CONTAINERS_RELATIVE, TOWER_MACOS_TOOL_EXPORT_RELATIVE (+5 more)
 * depends    src/save/battle/history
 * used by    src/calculators/specs.generated, src/node/find-export, src/save/access/index
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { countImportableBattleRuns } from '../battle/history'

/** Official The Tower Android package id (Idle Tower Defense). */
export const TOWER_ANDROID_PACKAGE = 'com.TechTreeGames.TheTower'

export const TOWER_PLAYER_INFO_FILENAME = 'playerInfo.dat'
/** Official export written under Application.persistentDataPath. */
export const TOWER_TOOL_EXPORT_FILENAME = 'tool_export.json'
export const TOWER_SAVE_FILENAMES = [TOWER_TOOL_EXPORT_FILENAME] as const
export const TOWER_ANDROID_TOOL_EXPORT_RELATIVE = `files/${TOWER_TOOL_EXPORT_FILENAME}`

/** Android's external persistentDataPath aliases, independent of transport. */
export function towerAndroidExportPaths(userId = 0): string[] {
  if (!Number.isInteger(userId) || userId < 0) throw new Error('Android user id must be a non-negative integer')
  const directory = `Android/data/${TOWER_ANDROID_PACKAGE}/files/${TOWER_TOOL_EXPORT_FILENAME}`
  return [`/storage/emulated/${userId}/${directory}`, ...(userId === 0 ? [`/sdcard/${directory}`] : [])]
}

/** Where macOS keeps app containers, relative to the home folder. */
export const TOWER_MACOS_CONTAINERS_RELATIVE = 'Library/Containers'
/** Where the game writes its export inside its macOS container. */
export const TOWER_MACOS_TOOL_EXPORT_RELATIVE = `Data/Documents/${TOWER_TOOL_EXPORT_FILENAME}`

/**
 * The export's path on a Mac, for one container.
 *
 * The game runs on a Mac as an iOS app, and macOS names that container after a UUID that differs
 * per install (`D26913FA-…`), not after the bundle id — so the folder has to be found by scanning
 * `~/Library/Containers`; `findToolExport` in the `/node` entry does that.
 */
export function towerMacExportPath(home: string, containerId: string): string {
  if (!containerId || containerId.includes('/') || containerId.includes('\\')) {
    throw new Error('macOS container id must be one folder name')
  }
  const base = home.endsWith('/') ? home.slice(0, -1) : home
  return `${base}/${TOWER_MACOS_CONTAINERS_RELATIVE}/${containerId}/${TOWER_MACOS_TOOL_EXPORT_RELATIVE}`
}

export const TOWER_ANDROID_PLAYER_INFO_SAVE_RELATIVE = `files/${TOWER_PLAYER_INFO_FILENAME}`

export function normalizePlayerInfoSourcePath(sourcePath: string): string {
  return String(sourcePath ?? '').trim().replace(/\\/g, '/')
}

/**
 * True when playerInfo.dat sits directly under Android/data/<package>/ instead of .../files/.
 * Also handles folder-picker relative paths like com.TechTreeGames.TheTower/playerInfo.dat.
 */
export function isMisplacedAndroidDataPlayerInfoPath(sourcePath: string): boolean {
  const normalized = normalizePlayerInfoSourcePath(sourcePath)
  if (!normalized) return false
  if (!/(^|\/)playerinfo\.dat$/i.test(normalized)) return false

  const androidDataMatch = normalized.match(/\/android\/data\/[^/]+\/(.+)$/i)
  if (androidDataMatch) {
    const afterPackage = androidDataMatch[1]
    if (/^files\//i.test(afterPackage)) return false
    return /^playerinfo\.dat$/i.test(afterPackage)
  }

  const segments = normalized.split('/').filter(Boolean)
  const fileName = segments.at(-1)
  if (!fileName || !/^playerinfo\.dat$/i.test(fileName)) return false
  const parent = segments.at(-2)
  if (!parent || /^files$/i.test(parent)) return false

  if (/techtree|thetower/i.test(parent)) return true
  if (/\.[A-Za-z][A-Za-z0-9_.-]*$/i.test(parent)) return true
  return false
}

export function looksLikeMisplacedParentPlayerInfoContent(
  parsedRoot: Record<string, unknown>,
  options?: { wasGzip?: boolean },
): boolean {
  if (options?.wasGzip !== false) return false
  if (countImportableBattleRuns(parsedRoot) > 0) return false
  const keyCount = Object.keys(parsedRoot).length
  if (keyCount <= 1) return false
  return true
}
